def best_breaks(words, width):
    """Return (minimum total penalty, list of lines)."""
    lines, current = [], words[0] if words else ""
    for w in words[1:]:
        if len(current) + 1 + len(w) <= width:
            current += " " + w
        else:
            lines.append(current)
            current = w
    if words:
        lines.append(current)
    return sum((width - len(l)) ** 2 for l in lines[:-1]), lines
